import React, { useMemo, useState } from "react"
import { Link } from "gatsby"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import { DataTable, Delta, MetricCard, Sparkline, TickerMark } from "../components/ui"

import { getWatchlist, getSparkline, getMarketBreadth } from "../data/markets"
import { getIndicators } from "../data/indicators"
import { getLatestNews } from "../data/news"
import { describeSource } from "../data/source"

/**
 * Watchlist.
 *
 * The tracked names in one table: price, the session move, where each sits
 * inside its own recent range, and whether the engine currently likes it.
 *
 * WHY THIS IS NOT A PRICE LIST. A price on its own answers nothing — a stock
 * at $13 is neither cheap nor expensive without the range it has been trading
 * in. Each row therefore carries its 20-day range position, its trend shape
 * and its signal bias, which together say whether a move is notable or noise.
 *
 * NOTHING IS BUCKETED IN ADVANCE. "Advancing" means the measured change is
 * above zero, computed here; and a name with no signals reads "no signals"
 * rather than a zero that would look like a bearish verdict.
 */

const DASH = "—"
const isNum = v => typeof v === "number" && Number.isFinite(v)
const usd = (v, d = 2) => (isNum(v) ? "$" + v.toFixed(d) : DASH)

const FILTERS = [
  { key: "all", label: "All" },
  { key: "up", label: "Advancing" },
  { key: "down", label: "Declining" },
  { key: "bullish", label: "Bullish signals" },
]

function Identity({ symbol, name }) {
  return (
    <span className="identity">
      <TickerMark symbol={symbol} size={26} />
      <span className="identity__text">
        <span className="identity__symbol">{symbol}</span>
        <span className="identity__name">{name}</span>
      </span>
    </span>
  )
}

/**
 * Where price sits inside its own recent range, 0–100.
 *
 * Returns null rather than a number when there is too little history. A
 * symbol listed weeks ago genuinely has no range to sit inside, and 0 would
 * read as "at the bottom of its range" — a claim the data cannot support.
 */
function rangePosition(symbol) {
  try {
    const ind = getIndicators(symbol, "3M")
    const closes = (ind.closes || []).filter(isNum).slice(-40)
    if (closes.length < 5) return null
    const lo = Math.min(...closes)
    const hi = Math.max(...closes)
    if (hi === lo) return null
    return ((closes[closes.length - 1] - lo) / (hi - lo)) * 100
  } catch {
    return null
  }
}

export default function WatchlistPage({ location }) {
  const [filter, setFilter] = useState("all")

  const all = useMemo(() => getWatchlist(), [])
  const breadth = useMemo(() => getMarketBreadth(), [])
  const source = useMemo(() => describeSource(), [])

  const enriched = useMemo(
    () =>
      all.map(r => ({
        ...r,
        rangePct: rangePosition(r.symbol),
        trend: getSparkline ? getSparkline(r.symbol) : null,
      })),
    [all]
  )

  const rows = useMemo(() => {
    if (filter === "up") return enriched.filter(r => (r.changePct ?? 0) > 0)
    if (filter === "down") return enriched.filter(r => (r.changePct ?? 0) < 0)
    if (filter === "bullish") return enriched.filter(r => (r.bullish ?? 0) > 0)
    return enriched
  }, [enriched, filter])

  const ranked = useMemo(
    () => [...enriched].sort((a, b) => (b.changePct ?? 0) - (a.changePct ?? 0)),
    [enriched]
  )
  const best = ranked[0] || null
  const worst = ranked[ranked.length - 1] || null
  const bullishCount = enriched.filter(r => (r.bullish ?? 0) > 0).length
  const latest = useMemo(() => (getLatestNews ? getLatestNews(6) : []), [])

  const columns = [
    {
      key: "symbol", header: "Symbol", width: "220px",
      sortValue: r => r.symbol,
      render: r => <Identity symbol={r.symbol} name={r.name} />,
    },
    {
      key: "price", header: "Price", numeric: true, align: "right",
      sortValue: r => r.price, render: r => usd(r.price),
    },
    {
      key: "changeAbs", header: "Today", align: "right", mobile: false,
      sortValue: r => r.changeAbs,
      render: r => <Delta value={r.changeAbs} digits={2} showGlyph={false} />,
    },
    {
      key: "changePct", header: "Change", align: "right",
      sortValue: r => r.changePct,
      render: r => <Delta value={r.changePct} percent digits={2} />,
    },
    {
      key: "rangePct", header: "20-day range", align: "right", mobile: false,
      sortValue: r => (isNum(r.rangePct) ? r.rangePct : -1),
      render: r =>
        isNum(r.rangePct) ? (
          <span className="watchlist__range" title="Position inside the recent trading range">
            <span className="watchlist__range-track">
              <span className="watchlist__range-fill" style={{ width: `${r.rangePct}%` }} />
            </span>
            <span className="watchlist__range-value">{r.rangePct.toFixed(0)}%</span>
          </span>
        ) : (
          <span className="watchlist__none">not enough history</span>
        ),
    },
    {
      key: "bias", header: "Signals", align: "right", mobile: false,
      sortValue: r => r.bullish ?? 0,
      render: r =>
        isNum(r.total) && r.total > 0 ? (
          <span className="watchlist__bias">
            {r.bullish}/{r.total} bullish
          </span>
        ) : (
          <span className="watchlist__none">no signals</span>
        ),
    },
    {
      key: "trend", header: "Trend", align: "right", sortable: false,
      render: r => (r.trend ? <Sparkline trend={r.trend} width={80} height={22} /> : DASH),
    },
  ]

  return (
    <Shell location={location}>
      <div className="page">
        <header className="page__head">
          <div className="page__heading">
            <Breadcrumb items={[{ label: "MarketScan", to: "/" }, { label: "Watchlist" }]} />
            <h1 className="page__title">Watchlist</h1>
            <p className="page__lede">
              The names being tracked, how they moved today, and where they sit in their own
              recent range.
            </p>
          </div>
          <div className="page__aside">
            <span className="watchlist__source">{source.label}</span>
          </div>
        </header>

        <section className="section">
          <div className="markets__metrics">
            <MetricCard label="Tracked" value={all.length} meta="names in the universe" />
            <MetricCard
              label="Advancing"
              value={breadth.advancing}
              unit={`/ ${breadth.total}`}
              meta="up on the session"
              tone={breadth.pct >= 50 ? "up" : "down"}
              bar={breadth.pct}
            />
            <MetricCard
              label="Best today"
              value={best ? best.symbol : DASH}
              meta={best && isNum(best.changePct) ? `${best.changePct > 0 ? "+" : ""}${best.changePct.toFixed(2)}%` : ""}
              tone="up"
            />
            <MetricCard
              label="Weakest today"
              value={worst ? worst.symbol : DASH}
              meta={worst && isNum(worst.changePct) ? `${worst.changePct.toFixed(2)}%` : ""}
              tone="down"
            />
          </div>
        </section>

        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">Tracked names</h2>
              <p className="section__subtitle">
                {bullishCount} of {all.length} currently carry a bullish signal.
              </p>
            </div>
            <div className="watchlist__filters" role="tablist" aria-label="Filter">
              {FILTERS.map(f => (
                <button
                  key={f.key}
                  type="button"
                  role="tab"
                  aria-selected={f.key === filter}
                  className={"watchlist__filter" + (f.key === filter ? " is-active" : "")}
                  onClick={() => setFilter(f.key)}
                >
                  {f.label}
                </button>
              ))}
            </div>
          </div>

          <Panel flush>
            <DataTable
              columns={columns}
              rows={rows}
              rowKey={r => r.symbol}
              initialSort={{ key: "changePct", direction: "desc" }}
              minWidth={980}
              emptyMessage="No names match this filter right now."
            />
          </Panel>
        </section>

        <section className="section">
          <div className="section__head">
            <div className="section__heading">
              <h2 className="section__title">Latest on these names</h2>
            </div>
            <Link className="btn btn--secondary btn--sm" to="/news/">
              All news
            </Link>
          </div>
          <Panel>
            <ul className="watchlist__news">
              {latest.map(item => (
                <li className="watchlist__news-item" key={item.id}>
                  <TickerMark symbol={item.symbol} size={22} />
                  <a
                    className="watchlist__news-link"
                    href={item.url}
                    target="_blank"
                    rel="noreferrer noopener"
                  >
                    {item.headline}
                  </a>
                  <span className="watchlist__news-source">{item.source}</span>
                </li>
              ))}
            </ul>
          </Panel>
        </section>
      </div>
    </Shell>
  )
}

export const Head = () => <title>Watchlist · MarketScan</title>
